#include "yoyo/plugin.h"

/*
 * cgo cannot pass a Go function pointer to C, so this tiny C shim is the
 * trampoline that the runtime actually registers.  go_yoyo_event is
 * generated by cgo from the //export in main.go.
 */
extern void go_yoyo_event(void *user, int type, const void *event);

void yoyo_register_go_callbacks(const yoyo_api *api) {
    (void)api->register_event(YOYO_EVENT_PRE_JOIN, go_yoyo_event, 0);
    (void)api->register_event(YOYO_EVENT_JOIN, go_yoyo_event, 0);
    (void)api->register_event(YOYO_EVENT_CHAT, go_yoyo_event, 0);
    (void)api->register_event(YOYO_EVENT_LEFT, go_yoyo_event, 0);
}
